/**
 * FilterManager.js
 * Manages PixiJS filters for visual polish
 * Priority 1: Visual Enhancement
 */

export class FilterManager {
    constructor() {
        this.filters = {
            glow: null,
            blur: null,
            dropShadow: null,
            colorMatrix: null
        };
        this.initialized = false;
    }

    /**
     * Initialize filters
     */
    async initialize() {
        if (this.initialized) return true;

        try {
            // PixiJS v8 has filters built-in
            // Filters are created on-demand, no need to pre-create
            this.initialized = true;
            return true;
        } catch (error) {
            console.warn('Filter initialization failed:', error);
            return false;
        }
    }


    /**
     * Apply glow to sprite
     */
    applyGlow(sprite, color = 0x8b5cf6, distance = 15) {
        if (!this.initialized) this.initialize();
        
        try {
            // Use PixiJS built-in filters
            import('pixi.js').then((PIXI) => {
                // Create glow effect using BlurFilter + ColorMatrix
                const blur = new PIXI.filters.BlurFilter({ strength: distance / 2 });
                const colorMatrix = new PIXI.filters.ColorMatrixFilter();
                
                // Set color tint
                const r = ((color >> 16) & 0xFF) / 255;
                const g = ((color >> 8) & 0xFF) / 255;
                const b = (color & 0xFF) / 255;
                
                colorMatrix.matrix = [
                    r, 0, 0, 0, 0,
                    0, g, 0, 0, 0,
                    0, 0, b, 0, 0,
                    0, 0, 0, 1, 0
                ];
                
                if (sprite.filters) {
                    sprite.filters.push(blur, colorMatrix);
                } else {
                    sprite.filters = [blur, colorMatrix];
                }
            });
            return true;
        } catch (error) {
            console.warn('Failed to apply glow:', error);
            return false;
        }
    }

    /**
     * Apply blur to sprite
     */
    applyBlur(sprite, strength = 4) {
        if (!this.initialized) this.initialize();
        
        try {
            import('pixi.js').then((PIXI) => {
                const blur = new PIXI.filters.BlurFilter({ strength, quality: 4 });
                
                if (sprite.filters) {
                    sprite.filters.push(blur);
                } else {
                    sprite.filters = [blur];
                }
            });
            return true;
        } catch (error) {
            console.warn('Failed to apply blur:', error);
            return false;
        }
    }

    /**
     * Apply drop shadow to sprite
     */
    applyDropShadow(sprite, options = {}) {
        if (!this.initialized) this.initialize();
        
        const {
            color = 0x000000,
            alpha = 0.5,
            blur = 4,
            offsetX = 2,
            offsetY = 2
        } = options;
        
        try {
            import('pixi.js').then((PIXI) => {
                // Create shadow using BlurFilter
                const shadowBlur = new PIXI.filters.BlurFilter({ strength: blur });
                const colorMatrix = new PIXI.filters.ColorMatrixFilter();
                
                // Darken and set alpha
                colorMatrix.brightness(-0.5, false);
                colorMatrix.alpha(alpha);
                
                // Apply offset by adjusting sprite position or using container
                if (sprite.filters) {
                    sprite.filters.push(shadowBlur, colorMatrix);
                } else {
                    sprite.filters = [shadowBlur, colorMatrix];
                }
                
                // Note: For true drop shadow with offset, need to use container or custom filter
            });
            return true;
        } catch (error) {
            console.warn('Failed to apply drop shadow:', error);
            return false;
        }
    }

    /**
     * Apply color adjustment
     */
    applyColorAdjustment(sprite, brightness = 0, contrast = 0, saturation = 0) {
        if (!this.initialized) this.initialize();
        
        try {
            import('pixi.js').then((PIXI) => {
                const colorMatrix = new PIXI.filters.ColorMatrixFilter();
                
                if (brightness !== 0) colorMatrix.brightness(brightness, false);
                if (contrast !== 0) colorMatrix.contrast(contrast, false);
                if (saturation !== 0) colorMatrix.saturate(saturation, false);
                
                if (sprite.filters) {
                    sprite.filters.push(colorMatrix);
                } else {
                    sprite.filters = [colorMatrix];
                }
            });
            return true;
        } catch (error) {
            console.warn('Failed to apply color adjustment:', error);
            return false;
        }
    }

    /**
     * Remove all filters from sprite
     */
    removeFilters(sprite) {
        sprite.filters = null;
    }
}

